// SPDX-License-Identifier: MIT
pragma solidity ^0.8.9;

import "@openzeppelin/contracts-upgradeable/token/ERC1155/ERC1155Upgradeable.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/token/ERC1155/extensions/ERC1155SupplyUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/token/ERC1155/utils/ERC1155HolderUpgradeable.sol";

contract KojoERC1155 is
  Initializable,
  ERC1155Upgradeable,
  OwnableUpgradeable,
  ERC1155HolderUpgradeable,
  ERC1155SupplyUpgradeable
{
  mapping(uint256 => string) private _uris;

  uint256 public fungibleTokenId;
  uint256 public nonFungibleTokenCount;

  /// @custom:oz-upgrades-unsafe-allow constructor
  constructor() {
     _disableInitializers();
  }

  // Initialize token contract.
  function __KojoERC1155_init() internal onlyInitializing {
    __ERC1155_init_unchained("");
    __Ownable_init_unchained();
    __ERC1155Supply_init_unchained();

    fungibleTokenId = 0;
    nonFungibleTokenCount = 1;

    setTokenUri(fungibleTokenId, "https://ipfs.io/ipfs/QmR5vt8PED7sxjXzvQf1JPeeGQcdce3jfCDCWDKyxhsi2z");
  }

  function supportsInterface(bytes4 interfaceId) public view virtual override(ERC1155Upgradeable, ERC1155ReceiverUpgradeable) returns (bool) {
    return super.supportsInterface(interfaceId);
  }

  // Allows to owner to update the metadata.
  function setURI(string memory newuri) public onlyOwner {
    _setURI(newuri);
  }

  // Allows the owner to mint tokens of multiple types.
  function mintBatch(
    address to,
    uint256[] memory ids,
    uint256[] memory amounts,
    bytes memory data
  ) public onlyOwner {
    _mintBatch(to, ids, amounts, data);
  }

  // The following functions are overrides required by Solidity.
  function _beforeTokenTransfer(
    address operator,
    address from,
    address to,
    uint256[] memory ids,
    uint256[] memory amounts,
    bytes memory data
  ) internal override(ERC1155Upgradeable, ERC1155SupplyUpgradeable) {
    super._beforeTokenTransfer(operator, from, to, ids, amounts, data);
  }

  // Increment the non-fungible token count.
  function handleIncrementTokenCount() internal {
    nonFungibleTokenCount += 1;
  }

  // Overwrite existing uri function to allow token specific uri's.
  function uri(uint256 tokenId) public view override returns (string memory) {
    return (_uris[tokenId]);
  }

  // Allow the owner to set token specific token uri.
  function setTokenUri(uint256 tokenId, string memory tokenURI) internal {
    _uris[tokenId] = tokenURI;
  }

  /**
   * Override isApprovedForAll to auto-approve OpenSea's proxy contract
   */
  function isApprovedForAll(
      address _owner,
      address _operator
  ) public override view returns (bool isOperator) {
      // if OpenSea's ERC1155 Proxy Address is detected, auto-return true
      if (_operator == address(0x207Fa8Df3a17D96Ca7EA4f2893fcdCb78a304101)) {
          return true;
      }
      // otherwise, use the default ERC1155Upgradeable.isApprovedForAll()
      return ERC1155Upgradeable.isApprovedForAll(_owner, _operator);
  }
}

contracts/utils/KojoUtils.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.9;

import "../utils/KojoLibrary.sol";
import "@openzeppelin/contracts-upgradeable/utils/StringsUpgradeable.sol";

contract KojoUtils {
  function handleBuildURI(Structs.Plant memory plant)
    external
    pure
    returns (string memory _uri)
  {
    // Perform some checks
    require(plant.isPresent, "Plant does not exist.");
    require(
      plant.level == 1
      || plant.level == 2
      || plant.level == 3
      || plant.level == 4
      || plant.level == 5,
      "Plant level does not exist."
    );
    require(
      plant.lifes == 1
      || plant.lifes == 2
      || plant.lifes == 3,
      "Plant lifes does not exist."
    );

    string memory base = "https://ipfs.io/ipfs/Qmayj2bo241oD2Xrkcpd8g76usfnK6sbLt9ZuvUJ4k6aXj/";
    string memory result = string(abi.encodePacked(
      base,
      StringsUpgradeable.toString(plant.typeId),
      "-",
      StringsUpgradeable.toString(plant.level),
      ".json"
    ));

    return result;
  }

  function handleRemoveTokenIdFromParticipant(
    Structs.Participant memory participant,
    uint256 tokenId
  ) external pure returns (Structs.Participant memory _participant) {
    uint256[] memory results = new uint256[](participant.plantIds.length - 1);

    for (uint256 i = 0; i < participant.plantIds.length; i++) {
      uint256 currentId = participant.plantIds[i];
      if (currentId != tokenId) {
        results[i] = currentId;
      }
    }

    participant.plantIds = results;

    return participant;
  }

  function handleCalculateAllowedTokenBalanceFromParticipantLevel(
    Structs.Participant memory participant,
    uint256 amount
  ) external pure returns (uint256 _amount) {
    // Increase multiplier as participant level increases.
    return amount + ((amount * (participant.level - 1)) / 10);
  }

  function handleAddXPToParticipant(
    Structs.Participant memory participant,
    uint256 amount,
    uint256 levelCost
  ) external pure returns (Structs.Participant memory _participant) {
    participant.experiencePoints += amount;

    uint256 newLevel = 1 + (participant.experiencePoints / levelCost);
    if (newLevel > 1) {
      participant.level = newLevel;
    }

    return participant;
  }

  function calculateParticipantLevelCost(
    uint256 levelCost,
    uint256 level
  ) external pure returns (uint256) {
    // Increase level cost as participant level increases.
    uint256 participantLevelCost = levelCost + ((level - 1) * 10);

    return participantLevelCost;
  }

  function handleAddXPToPlant(Structs.Plant memory plant, uint256 amount)
    external
    pure
    returns (Structs.Plant memory _plant)
  {
    plant.experiencePoints += amount;

    uint256 newLevel = 1 + (plant.experiencePoints / plant.levelCost);
    if (newLevel > 1 && newLevel <= 5) {
      plant.level = newLevel;
    } else if (newLevel > 5) {
      plant.level = 5;
    }

    return plant;
  }

  function bytesToAddress(bytes calldata data) external pure returns (address addr) {
    bytes memory b = data;

    assembly {
      addr := mload(add(b, 20))
    }
  }

  function encodeAddressArray(address[] calldata addresses) external pure returns (bytes memory) {
    bytes memory data;

    for (uint256 i = 0; i < addresses.length; i++){
      data = abi.encodePacked(data, addresses[i]);
    }

    return data;
  }
}

